         al_get_bitmap_width(bitmap), al_get_bitmap_height(bitmap),
         0, 0, 320, 240, 0);
      al_flip_display();
      al_destroy_bitmap(bitmap);
   }

   al_destroy_display(display);
   return 0;
}

