#include <stdio.h>
#include "allegro5/allegro.h"
#include "allegro5/allegro_image.h"
#include "allegro5/allegro_opengl.h"

int main(int argc, char **argv)
{
   int i;
   al_init();
   al_init_image_addon();
   if (!al_create_display(64, 64)) return 1;
   for (i = 1; i < argc; i++) {
      ALLEGRO_BITMAP *b = al_load_bitmap(argv[i]);
      ALLEGRO_BITMAP *c;
      ALLEGRO_LOCKED_REGION *lr;
      int fmt;
      if (!b) { printf("load fail %s\n", argv[i]); return 2; }
      fmt = al_get_bitmap_format(b);
      al_set_new_bitmap_format(fmt);
      al_set_new_bitmap_flags(ALLEGRO_VIDEO_BITMAP);
      c = al_clone_bitmap(b);
      if (!c) { printf("clone fail %s\n", argv[i]); return 3; }
      while (glGetError());
      lr = al_lock_bitmap_blocked(c, ALLEGRO_LOCK_READWRITE);
      if (!lr) { printf("lock fail %s\n", argv[i]); return 4; }
      al_unlock_bitmap(c);
      printf("%s lock glerr=%x\n", argv[i], glGetError());
      al_destroy_bitmap(c);
      al_destroy_bitmap(b);
   }
   return 0;
}

